
(function(){
  var reduceMotion = window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches;
  var isFinePointer = window.matchMedia && window.matchMedia('(pointer:fine)').matches;

  /* Theme toggle */
  var root = document.documentElement;
  var themeBtn = document.getElementById('themeToggle');
  function applyTheme(t){
    root.setAttribute('data-theme', t === 'light' ? 'light' : 'dark');
    themeBtn.textContent = t === 'light' ? '◑' : '◐';
  }
  var saved = null;
  try{ saved = localStorage.getItem('akshita-theme'); }catch(e){}
  if(!saved){ saved = (window.matchMedia && window.matchMedia('(prefers-color-scheme: light)').matches) ? 'light' : 'dark'; }
  applyTheme(saved);
  themeBtn.addEventListener('click', function(){
    var current = root.getAttribute('data-theme') === 'light' ? 'light' : 'dark';
    var next = current === 'light' ? 'dark' : 'light';
    applyTheme(next);
    try{ localStorage.setItem('akshita-theme', next); }catch(e){}
  });

  /* Mobile nav */
  var navToggleBtn = document.getElementById('navToggleBtn');
  var navLinks = document.getElementById('navLinks');
  navToggleBtn.addEventListener('click', function(){
    var open = navLinks.classList.toggle('open');
    navToggleBtn.setAttribute('aria-expanded', open ? 'true':'false');
  });
  document.querySelectorAll('.nav-a').forEach(function(a){
    a.addEventListener('click', function(){ navLinks.classList.remove('open'); });
  });

  /* Nav scroll state, active link, progress bar */
  var nav = document.getElementById('nav');
  var progress = document.getElementById('progress');
  var sections = Array.prototype.slice.call(document.querySelectorAll('section[id]'));
  var navAs = Array.prototype.slice.call(document.querySelectorAll('.nav-a'));
  function onScroll(){
    nav.classList.toggle('scrolled', window.scrollY > 12);
    var scrollPos = window.scrollY + 120;
    var current = sections[0];
    sections.forEach(function(s){ if(s.offsetTop <= scrollPos) current = s; });
    navAs.forEach(function(a){ a.classList.toggle('active', a.getAttribute('href') === '#' + current.id); });
    var docH = document.documentElement.scrollHeight - window.innerHeight;
    progress.style.width = (docH > 0 ? (window.scrollY/docH)*100 : 0) + '%';
  }
  window.addEventListener('scroll', onScroll, {passive:true});
  onScroll();

  /* Reveal on scroll */
  var revealEls = document.querySelectorAll('.reveal');
  if('IntersectionObserver' in window){
    var io = new IntersectionObserver(function(entries){
      entries.forEach(function(entry){
        if(entry.isIntersecting){ entry.target.classList.add('in'); io.unobserve(entry.target); }
      });
    }, {threshold:0.15});
    revealEls.forEach(function(el){ io.observe(el); });
  } else {
    revealEls.forEach(function(el){ el.classList.add('in'); });
  }

  /* Custom cursor */
  if(isFinePointer){
    document.body.classList.add('has-cursor');
    var dot = document.getElementById('cursor-dot');
    var ring = document.getElementById('cursor-ring');
    var rx=0, ry=0, mx=0, my=0;
    window.addEventListener('mousemove', function(e){
      mx = e.clientX; my = e.clientY;
      dot.style.transform = 'translate('+mx+'px,'+my+'px) translate(-50%,-50%)';
    });
    function ringLoop(){
      rx += (mx-rx)*0.18; ry += (my-ry)*0.18;
      ring.style.transform = 'translate('+rx+'px,'+ry+'px) translate(-50%,-50%)';
      requestAnimationFrame(ringLoop);
    }
    ringLoop();
    document.querySelectorAll('a, button, .skill-node, .project-flip, input, textarea').forEach(function(el){
      el.addEventListener('mouseenter', function(){ ring.classList.add('grow'); });
      el.addEventListener('mouseleave', function(){ ring.classList.remove('grow'); });
    });
    /* Magnetic buttons */
    document.querySelectorAll('.magnetic').forEach(function(el){
      el.addEventListener('mousemove', function(e){
        var r = el.getBoundingClientRect();
        var relX = e.clientX - r.left - r.width/2;
        var relY = e.clientY - r.top - r.height/2;
        el.style.transform = 'translate('+(relX*0.25)+'px,'+(relY*0.35)+'px)';
      });
      el.addEventListener('mouseleave', function(){ el.style.transform = 'translate(0,0)'; });
    });
  }

  /* Typewriter tagline */
  var phrases = [
    'Building scalable, user-focused applications.',
    'Designing safety-first interfaces.',
    'Shipping cloud & API-driven systems.',
    'Contributing to open source, one PR at a time.'
  ];
  var typeTarget = document.getElementById('typeTarget');
  if(reduceMotion){
    typeTarget.textContent = phrases[0];
  } else {
    var pIdx=0, cIdx=0, deleting=false;
    function typeLoop(){
      var current = phrases[pIdx];
      if(!deleting){
        cIdx++;
        typeTarget.textContent = current.slice(0,cIdx);
        if(cIdx === current.length){ deleting = true; setTimeout(typeLoop, 1600); return; }
      } else {
        cIdx--;
        typeTarget.textContent = current.slice(0,cIdx);
        if(cIdx === 0){ deleting = false; pIdx = (pIdx+1)%phrases.length; }
      }
      setTimeout(typeLoop, deleting ? 28 : 48);
    }
    typeLoop();
  }

  /* Hero network canvas */
  var canvas = document.getElementById('hero-canvas');
  var ctx = canvas.getContext('2d');
  var heroSection = document.getElementById('hero');
  var nodes = [];
  var mouseP = {x:null,y:null};
  var animId = null;

  function resizeCanvas(){
    var rect = heroSection.getBoundingClientRect();
    canvas.width = rect.width * devicePixelRatio;
    canvas.height = rect.height * devicePixelRatio;
    canvas.style.width = rect.width+'px';
    canvas.style.height = rect.height+'px';
    ctx.setTransform(devicePixelRatio,0,0,devicePixelRatio,0,0);
    var count = Math.min(70, Math.floor(rect.width*rect.height/16000));
    nodes = [];
    for(var i=0;i<count;i++){
      nodes.push({
        x: Math.random()*rect.width,
        y: Math.random()*rect.height,
        vx: (Math.random()-0.5)*0.25,
        vy: (Math.random()-0.5)*0.25
      });
    }
  }

  function getAccentColor(){
    return getComputedStyle(root).getPropertyValue('--accent').trim() || '#2fd7c9';
  }

  function drawFrame(){
    var rect = heroSection.getBoundingClientRect();
    ctx.clearRect(0,0,rect.width,rect.height);
    var accent = getAccentColor();
    var accRgb = hexToRgb(accent);

    nodes.forEach(function(n){
      n.x += n.vx; n.y += n.vy;
      if(mouseP.x !== null){
        var dx = n.x - mouseP.x, dy = n.y - mouseP.y;
        var dist = Math.sqrt(dx*dx+dy*dy);
        if(dist < 130){
          var force = (130-dist)/130 * 0.6;
          n.vx += (dx/dist)*force*0.02;
          n.vy += (dy/dist)*force*0.02;
        }
      }
      n.vx *= 0.98; n.vy *= 0.98;
      if(n.x < 0 || n.x > rect.width) n.vx *= -1;
      if(n.y < 0 || n.y > rect.height) n.vy *= -1;
      n.x = Math.max(0, Math.min(rect.width, n.x));
      n.y = Math.max(0, Math.min(rect.height, n.y));
    });

    for(var i=0;i<nodes.length;i++){
      for(var j=i+1;j<nodes.length;j++){
        var a = nodes[i], b = nodes[j];
        var dx = a.x-b.x, dy = a.y-b.y;
        var dist = Math.sqrt(dx*dx+dy*dy);
        if(dist < 130){
          ctx.strokeStyle = 'rgba('+accRgb+','+ (0.14*(1-dist/130)) +')';
          ctx.lineWidth = 1;
          ctx.beginPath();
          ctx.moveTo(a.x,a.y);
          ctx.lineTo(b.x,b.y);
          ctx.stroke();
        }
      }
    }
    nodes.forEach(function(n){
      ctx.fillStyle = 'rgba('+accRgb+',0.55)';
      ctx.beginPath();
      ctx.arc(n.x,n.y,1.6,0,Math.PI*2);
      ctx.fill();
    });

    animId = requestAnimationFrame(drawFrame);
  }

  function hexToRgb(hex){
    hex = hex.replace('#','');
    if(hex.length===3){ hex = hex.split('').map(function(c){return c+c;}).join(''); }
    var num = parseInt(hex,16);
    return [(num>>16)&255, (num>>8)&255, num&255].join(',');
  }

  heroSection.addEventListener('mousemove', function(e){
    var r = heroSection.getBoundingClientRect();
    mouseP.x = e.clientX - r.left;
    mouseP.y = e.clientY - r.top;
  });
  heroSection.addEventListener('mouseleave', function(){ mouseP.x = null; mouseP.y = null; });

  resizeCanvas();
  window.addEventListener('resize', resizeCanvas);
  if(!reduceMotion){
    drawFrame();
  } else {
    ctx.clearRect(0,0,canvas.width,canvas.height);
  }

  /* Photo ring subtle 3D tilt */
  var photoRing = document.getElementById('photoRing');
  if(isFinePointer && !reduceMotion){
    document.querySelector('.hero-photo-wrap').addEventListener('mousemove', function(e){
      var r = photoRing.getBoundingClientRect();
      var relX = (e.clientX - r.left - r.width/2) / r.width;
      var relY = (e.clientY - r.top - r.height/2) / r.height;
      photoRing.style.transform = 'rotateY('+(relX*14)+'deg) rotateX('+(-relY*14)+'deg)';
    });
    document.querySelector('.hero-photo-wrap').addEventListener('mouseleave', function(){
      photoRing.style.transform = 'rotateY(0) rotateX(0)';
    });
  }

  /* Animated stat counters */
  var statEls = document.querySelectorAll('.stat-num, .stat-num > span[data-target]');
  var countedTargets = document.querySelectorAll('#stats[data-target]');
  var counted = false;
  function animateCounters(){
    if(counted) return; counted = true;
    countedTargets.forEach(function(el){
      var target = parseFloat(el.getAttribute('data-target'));
      var decimals = parseInt(el.getAttribute('data-decimals') || '0', 10);
      var start = 0, duration = 1200, startTime = null;
      function step(ts){
        if(!startTime) startTime = ts;
        var progressT = Math.min((ts-startTime)/duration, 1);
        var eased = 1 - Math.pow(1-progressT, 3);
        var val = start + (target-start)*eased;
        el.textContent = decimals > 0 ? val.toFixed(decimals) : Math.round(val);
        if(progressT < 1) requestAnimationFrame(step);
      }
      requestAnimationFrame(step);
    });
  }
  var statsSection = document.getElementById('stats');
  if('IntersectionObserver' in window){
    var statObs = new IntersectionObserver(function(entries){
      entries.forEach(function(e){ if(e.isIntersecting){ animateCounters(); statObs.disconnect(); } });
    }, {threshold:0.4});
    statObs.observe(statsSection);
  } else { animateCounters(); }

  /* Project card glare + flip */
  document.querySelectorAll('.project-flip').forEach(function(card){
    var front = card.querySelector('.project-face.front');
    if(isFinePointer && !reduceMotion && front){
      card.addEventListener('mousemove', function(e){
        var r = card.getBoundingClientRect();
        var relX = (e.clientX - r.left)/r.width;
        var relY = (e.clientY - r.top)/r.height;
        front.style.setProperty('--mx', (relX*100)+'%');
        front.style.setProperty('--my', (relY*100)+'%');
      });
    }
  });
  document.querySelectorAll('.flip-btn').forEach(function(btn){
    btn.addEventListener('click', function(){
      document.getElementById(btn.getAttribute('data-target')).classList.toggle('flipped');
    });
  });

  /* Cert flip on tap for touch devices */
  document.querySelectorAll('.cert-flip').forEach(function(c){
    c.addEventListener('click', function(){
      if(!isFinePointer){ c.classList.toggle('flipped'); }
    });
  });
  /* Contact form */
var form = document.getElementById('contactForm');
var status = document.getElementById('formStatus');

form.addEventListener('submit', function(e){
  e.preventDefault();

  var name = document.getElementById('cname').value.trim();
  var email = document.getElementById('cemail').value.trim();
  var message = document.getElementById('cmessage').value.trim();

  var subject = encodeURIComponent('Portfolio contact from ' + name);
  var body = encodeURIComponent(
    message + '\n\nFrom: ' + email
  );

  window.location.href =
    'mailto:akshita05verma@gmail.com?subject=' +
    subject +
    '&body=' +
    body;
});
  document.getElementById('year').textContent = new Date().getFullYear();

  /* Assets */
  document.getElementById('heroPhoto').src = 'data:image/jpeg;base64,';
  document.getElementById('resumeBtn').href = 'data:application/pdf;base64,';
})();
